// Eight lines that say what ran, how it ended, what is waiting for a human,
// and whether the screening rules still agree with the labels.
//
// Deliberately short. A digest long enough to need scrolling is a digest
// people stop reading, and an unread digest is worse than none because it
// creates the belief that somebody is watching.

const d = $input.first().json;
const dl = d.dead_letters ?? {};
const ev = d.latest_eval ?? null;
const subs = d.submissions ?? {};
const pay = d.payouts ?? {};

const lines = [];
lines.push(`creator-program, last 24h`);
lines.push('');

if ((d.runs_24h ?? 0) === 0) {
  // The dead man's switch. Every other number in this digest describes work
  // that happened; only this one notices work that did not. A disabled
  // workflow, an expired credential or a trigger that stopped firing produce
  // no failures at all -- they produce silence, and silence reads exactly
  // like a quiet week.
  lines.push('NOTHING RAN. No run records in 24 hours.');
  lines.push('Check: workflow active, credentials valid, schedule firing.');
} else {
  for (const o of d.outcomes ?? []) {
    lines.push(`  ${o.kind.padEnd(10)} ${o.status.padEnd(10)} ${String(o.n).padStart(4)}  avg ${o.avg_ms}ms`);
  }
}

lines.push('');
lines.push(`Dead letters awaiting a decision: ${dl.open_total ?? 0}` +
  ` (${dl.open_today ?? 0} today, ${dl.open_invalid ?? 0} malformed, ${dl.open_crashed ?? 0} crashes)`);

if (dl.oldest_open) {
  const days = Math.floor((Date.now() - new Date(dl.oldest_open).getTime()) / 86400000);
  // Age, not just count. A DLQ holding steady at four is either four items
  // someone triages daily or the same four nobody has looked at since March,
  // and the count cannot tell those apart.
  lines.push(`Oldest open dead letter: ${days} day(s) old`);
}

lines.push(`Applicants awaiting human review: ${subs.awaiting_review ?? 0}` +
  ` (${subs.new_today ?? 0} new today)`);

lines.push(ev
  ? `Screening accuracy: ${ev.accuracy} (macro F1 ${ev.macro_f1}, ${ev.ruleset_version})`
  : 'Screening accuracy: never evaluated -- run 05');

if (pay.last_period_end) {
  lines.push(`Last payout period ${pay.last_period_end}: ${(pay.last_period_cents / 100).toFixed(2)} EUR`);
}

// What makes this worth a look rather than worth a scroll past.
const needsAttention =
  (d.runs_24h ?? 0) === 0 ||
  (d.failed_24h ?? 0) > 0 ||
  (dl.open_total ?? 0) > 0 ||
  (ev && ev.accuracy < Number($env.MIN_ACCURACY ?? 0.8));

return [{ json: {
  text: lines.join('\n'),
  needs_attention: needsAttention,
  silent: (d.runs_24h ?? 0) === 0,
} }];
